import ftplib
try:
    ftp = ftplib.FTP()
    ftp.connect('10.0.179.145', 2121, timeout=10)
    print('BANNER:', ftp.getwelcome())
    try:
        print('ANON LOGIN:', ftp.login('anonymous','test@test.com'))
        print('ANON OK - listing:')
        try:
            ftp.retrlines('LIST')
        except Exception as e:
            print('LIST err:', e)
    except Exception as e:
        print('ANON login failed:', e)
        try:
            print('user ftp:', ftp.login('ftp','ftp@ftp.com'))
        except Exception as e2:
            print('ftp login failed:', e2)
    ftp.quit()
except Exception as e:
    print('FTP ERR:', repr(e))
"

